#include "common.h"

u8 *func_8004E4C0(u32 n, u16 w, u8 *out, u8 pad)
{
    s32 i;
    u32 t;
    u16 lim = w;

    *out++ = n % 10 + 0x30;
    i = 1;
    if (i < lim)
    {
        while (i < lim)
        {
            n = n / 10;
            if (n == 0)
            {
                break;
            }
            t = n % 10;
            t += 0x30;
            *out++ = t;
            i++;
        }
        while (i < w)
        {
            *out++ = pad;
            i++;
        }
    }
    *out = 0;
    return out - w;
}
